  'partner-matrix': {title:'Partner & Opponent Matrix',definition:'A summary of the player’s most relevant recorded partner and opponent relationships.',formula:'Uses head-to-head and partnership performance compared with the player baseline.',interpretation:'Relationship insights become more reliable as the number of shared matches increases.'},
  'flpr-intelligence': {title:'FLPR Intelligence',definition:'A plain-language synthesis of the player’s current statistical profile.',formula:'Generated from the approved workbook metrics, reliability, current form, strengths, and risk factors.',interpretation:'Use this as an analytical summary and coaching aid, not as a substitute for direct observation.'},
  'coaching-priority': {title:'Coaching Priority',definition:'The single most relevant development focus identified from the player profile.',formula:'Selected from the weakest or most actionable verified performance dimensions.',interpretation:'It is a practical training direction, not a diagnosis or guaranteed path to improvement.'},
