  'development-areas': {title:'Development Areas',definition:'Performance dimensions with the clearest potential for improvement.',formula:'Lower relative metrics, recurring risk factors, or below-field indicators.',interpretation:'These are priorities for practice, not negative labels.'},
  'handicap-explanation': {title:'Handicap Explanation',definition:'Why the player currently receives the displayed FLPR handicap.',formula:'Summarizes the approved handicap policy applied to rating, ability, reliability, and match evidence.',interpretation:'The handicap aims to balance competitive opportunity while still reflecting real ability.'},
  'current-record': {title:'Current Record',definition:'The player’s current result and form snapshot across the approved dataset.',formula:'Combines match counts, wins, losses, win rate, recent form, expectation, consistency, and momentum.',interpretation:'Read volume and percentages together; small samples require caution.'},
  'rating-drivers': {title:'Rating Drivers',definition:'The factors currently supporting or limiting the player’s FLPR rating.',formula:'Positive and risk components supplied by the workbook rating analysis.',interpretation:'Drivers explain the rating context; they do not independently determine rank.'},
  'achievements': {title:'Achievements & Badges',definition:'Official recognition earned from ranking, performance thresholds, participation, or workbook awards.',formula:'Assigned only when the player meets the approved rule for each badge or award.',interpretation:'Badges recognize milestones and should not replace the complete scorecard.'},
  'best-partner-relation': {title:'Best Partner Relationship',definition:'The partner associated with the strongest positive recorded performance effect.',formula:'Partnership win rate and performance delta versus the player baseline, adjusted for sample size.',interpretation:'Strong chemistry is more credible when supported by several shared matches.'},
  'challenging-partner': {title:'Challenging Partner Relationship',definition:'A partner combination that has produced comparatively difficult results.',formula:'Partnership performance below the player baseline, adjusted for available sample size.',interpretation:'This may indicate style fit or limited evidence; it is not a judgment of either player.'},
  'hardest-opponent': {title:'Hardest Opponent',definition:'The opponent who has presented the greatest recorded head-to-head challenge.',formula:'Head-to-head win rate, point differential, and number of meetings combined.',interpretation:'A matchup can be difficult because of style, strength, or a small sample.'},
